insert into legal_sources (code, name, kind, reference, url, publisher, countries, published_on, published_by, description) values
  ('fr_code_energie',             'Code de l''énergie',                                                       'code',         'Code de l''énergie',                                                                              'https://www.legifrance.gouv.fr/codes/texte_lc/LEGITEXT000023983208/',              'Légifrance', '{FR}', null,         'pack:fr', 'Energy law: self-consumption (L. 315-1 and following), purchase obligation, connection, conformity of installations (D. 342-16 and following), meter data.'),
  ('fr_code_urbanisme',           'Code de l''urbanisme',                                                     'code',         'Code de l''urbanisme',                                                                            'https://www.legifrance.gouv.fr/codes/texte_lc/LEGITEXT000006074075/',              'Légifrance', '{FR}', null,         'pack:fr', 'Planning law: which works need no authorisation, a prior declaration or a building permit (R. 421-1 and following); solar on car parks (L. 111-19-1).'),
  ('fr_cch',                      'Code de la construction et de l''habitation',                              'code',         'Code de la construction et de l''habitation',                                                     'https://www.legifrance.gouv.fr/codes/texte_lc/LEGITEXT000006074096/',              'Légifrance', '{FR}', null,         'pack:fr', 'Building law: solar or green roofs on new commercial buildings (L. 171-4), energy performance of tertiary buildings (L. 174-1), the energy performance certificate (L. 126-26 and following).'),
  ('fr_code_environnement',       'Code de l''environnement',                                                 'code',         'Code de l''environnement',                                                                        'https://www.legifrance.gouv.fr/codes/texte_lc/LEGITEXT000006074220/',              'Légifrance', '{FR}', null,         'pack:fr', 'Environmental assessment: the table annexed to R. 122-2, item 30 for photovoltaic installations.'),
  ('fr_loi_aper_2023',            'Loi n° 2023-175 du 10 mars 2023 relative à l''accélération de la production d''énergies renouvelables', 'law', 'Loi n° 2023-175 du 10 mars 2023',                                            'https://www.legifrance.gouv.fr/jorf/id/JORFTEXT000047294244',                       'Légifrance', '{FR}', '2023-03-10', 'pack:fr', 'The acceleration law: solar on car parks of 1 500 m² and more (article 40), acceleration zones, agrivoltaics, wider self-consumption.'),
  ('fr_loi_climat_2021',          'Loi n° 2021-1104 du 22 août 2021 portant lutte contre le dérèglement climatique', 'law',    'Loi n° 2021-1104 du 22 août 2021',                                                                'https://www.legifrance.gouv.fr/jorf/id/JORFTEXT000043956924',                       'Légifrance', '{FR}', '2021-08-22', 'pack:fr', 'Climate and resilience law: solar or green roofs on new buildings of 500 m² and more (article 101), the energy performance certificate made enforceable.'),
  ('fr_arrete_2019_11_21_acc',    'Arrêté du 21 novembre 2019 fixant le critère de proximité géographique de l''autoconsommation collective étendue', 'order', 'Arrêté du 21 novembre 2019 (NOR: TRER1932587A), modifié par l''arrêté du 14 octobre 2020 et l''arrêté du 21 février 2025', 'https://www.legifrance.gouv.fr/loda/id/JORFTEXT000039417566/', 'Légifrance', '{FR}', '2019-11-21', 'pack:fr', 'The perimeter of an extended collective self-consumption operation (2 km, 10 km, 20 km) and the cumulative power of its installations (5 MW since the order of 21 February 2025).'),
  ('fr_arrete_2021_10_06_s21',    'Arrêté du 6 octobre 2021 fixant les conditions d''achat de l''électricité produite par les installations implantées sur bâtiment, hangar ou ombrière utilisant l''énergie solaire photovoltaïque', 'order', 'Arrêté du 6 octobre 2021 (« S21 »), modifié en dernier lieu par les arrêtés du 26 mars 2025, du 6 octobre 2025 et du 1er juin 2026', 'https://www.legifrance.gouv.fr/loda/id/JORFTEXT000044173284/', 'Légifrance', '{FR}', '2021-10-06', 'pack:fr', 'The purchase obligation and the self-consumption premium for photovoltaic installations on buildings, barns and carports, by quarterly tariff window.'),
  ('fr_decret_2022_970_ee',       'Décret n° 2022-970 du 1er juillet 2022 portant diverses dispositions relatives à l''évaluation environnementale des projets', 'decree', 'Décret n° 2022-970 du 1er juillet 2022',                                           'https://www.legifrance.gouv.fr/jorf/id/JORFTEXT000046000733',                       'Légifrance', '{FR}', '2022-07-01', 'pack:fr', 'Item 30 of the environmental assessment table: photovoltaic installations of 1 MWc and more assessed, 300 kWc to 1 MWc examined case by case.'),
  ('fr_decret_2019_771_tertiaire','Décret n° 2019-771 du 23 juillet 2019 relatif aux obligations d''actions de réduction de la consommation d''énergie finale dans des bâtiments à usage tertiaire', 'decree', 'Décret n° 2019-771 du 23 juillet 2019',                              'https://www.legifrance.gouv.fr/jorf/id/JORFTEXT000038812251',                       'Légifrance', '{FR}', '2019-07-23', 'pack:fr', 'The Éco Énergie Tertiaire scheme: tertiary buildings of 1 000 m² and more cut their final energy by 40 % in 2030, 50 % in 2040, 60 % in 2050, declared on OPERAT.'),
  ('fr_arrete_2021_03_31_dpe',    'Arrêté du 31 mars 2021 relatif au diagnostic de performance énergétique pour les bâtiments ou parties de bâtiments à usage d''habitation en France métropolitaine', 'order', 'Arrêté du 31 mars 2021 (NOR: LOGL2033917A)',                          'https://www.legifrance.gouv.fr/loda/id/JORFTEXT000043353381/',                      'Légifrance', '{FR}', '2021-03-31', 'pack:fr', 'The energy performance certificate of dwellings: the classes A to G on primary energy and greenhouse gas, in force since 1 July 2021.'),
  ('fr_cre_2025_13_turpe7',       'Délibération de la CRE n° 2025-13 du 30 janvier 2025 portant décision sur le tarif d''utilisation des réseaux publics de distribution d''électricité (TURPE 7 HTA-BT)', 'deliberation', 'Délibération CRE n° 2025-13 du 30 janvier 2025', 'https://www.cre.fr/documents/Deliberations/Decision/turpe-7-hta-bt', 'CRE', '{FR}', '2025-01-30', 'pack:fr', 'The seventh network tariff for distribution (HTA and BT), in force from 1 August 2025 for about four years: the components of what a grid user pays.'),
  ('fr_enedis_noi_cf_110e',       'Enedis-NOI-CF_110E — Modalités propres aux points de connexion participant à une opération d''autoconsommation collective', 'contract_model', 'Enedis-NOI-CF_110E, version 3.0 (janvier 2023)', 'https://www.enedis.fr/media/2910/download',                                        'Enedis',     '{FR}', '2023-01-01', 'pack:fr', 'How the distribution operator treats the connection points of a collective self-consumption operation: the allocation keys it applies (static, dynamic by default, dynamic custom) and the data it returns to the organising entity.'),
  ('fr_enedis_convention_acc',    'Convention d''autoconsommation collective Enedis / personne morale organisatrice', 'contract_model', 'Enedis-FOR-CF_01E, version 8.0 (février 2025)',                                             'https://www.enedis.fr/media/1881/download',                                        'Enedis',     '{FR}', '2025-02-01', 'pack:fr', 'The contract between the distribution operator and the organising entity of a collective self-consumption operation: perimeter, participants, keys, data, invoicing of the network.'),
  ('fr_enedis_data_connect_terms','Conditions d''utilisation d''Enedis Data Connect',                         'contract_model', 'Enedis Data Connect — conditions générales d''utilisation',                                       'https://datahub-enedis.fr/data-connect/',                                           'Enedis',     '{FR}', null,         'pack:fr', 'What a third party may read of a customer''s meter data with the customer''s consent: the scopes, the history, the duration of a consent.');
